from typing import Optional


class Headers:
    """
    A class to manage HTTP headers for requests and responses.

    Attributes
    ----------
    headers : dict
        A dictionary containing predefined header options for 'Content-Type' and 'Accept'.
        This dictionary can be extended with additional headers as needed.

    Methods
    -------
    get(**kwargs)
        Returns a dictionary of headers based on the provided arguments.
    """
    def __init__(self):
        self.headers = {
            "Content-Type": {
                "json": "application/json"
            },
            "accept": {
                "json": "application/json",
                "any": "*/*"
            }
        }

    def get(self, content_type: Optional[str] = None, accept: Optional[str] = None) -> dict:
        """
        Returns a dictionary of headers based on the provided arguments.

        :param content_type: media type of the resource being sent.
                            Available options: json
        :param accept: media type that the client is willing to accept in the response.
                      Available options: json, any

        :returns: dictionary of headers, for example {'Content-Type': 'application/json', 'accept': '*/*'}
        :rtype: dict
        """
        headers = {}
        if content_type:
            headers["Content-Type"] = self._get_content_type(content_type=content_type)
        if accept:
            headers["accept"] = self._get_accept_type(accept=accept)

        return headers

    def _get_content_type(self, content_type):
        try:
            return self.headers["Content-Type"][content_type]
        except KeyError:
            raise ValueError(f"Content-Type you gave: '{content_type}' "
                             f"is not one of the available options: {list(self.headers['Content-Type'].keys())}. "
                             f"Consider updating the 'headers' attribute with your content-type.")

    def _get_accept_type(self, accept):
        try:
            return self.headers["accept"][accept]
        except KeyError:
            raise ValueError(f"Accept type you gave: '{accept}' "
                             f"is not one of the available options: {list(self.headers['accept'].keys())}. "
                             f"Consider updating the 'headers' attribute with your accept type.")
